test.config:
indexer
{
	mem_limit = 16M
}
searchd
{

	pseudo_sharding = 1
}
source grouped_rankless_source
{
	type = mysql

	sql_query = SELECT id, body, gid FROM grouped_rankless_docs ORDER BY insertion_order
	sql_attr_uint = gid
}
index grouped_rankless_plain
{
	source = grouped_rankless_source
	path = /grouped_rankless_plain
}

queries.sphinxql:
SELECT gid,COUNT(*) n FROM grouped_rankless_plain WHERE MATCH('alpha') GROUP BY gid ORDER BY n DESC,gid ASC LIMIT 1,2 OPTION threads=2;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_group_rankless';
